import java.io.*;
import java.util.*;

import com.fasterxml.jackson.annotation.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.dataformat.csv.*;

public class Main {
    public static void main(String[] args) throws IOException {
        CsvMapper mapper = new CsvMapper();
        CsvSchema schema = mapper.schemaFor(Produk.class).withHeader();
        System.out.print(mapper.writer(schema).writeValueAsString(Arrays.asList(new Produk("Kopi", 18000, 5))));
    }
}

class Produk {
    public String nama;
    public int harga;
    public int stok;

    Produk(String nama, int harga, int stok) {
        this.nama = nama;
        this.harga = harga;
        this.stok = stok;
    }
}

