import java.io.*;
import java.util.*;

import com.fasterxml.jackson.annotation.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.dataformat.csv.*;

public class Main {
    public static void main(String[] args) throws IOException {
        CsvMapper mapper = new CsvMapper();
        CsvSchema schema = mapper.schemaFor(Todo.class).withHeader();
        List<Todo> daftar = Arrays.asList(new Todo(1, "Belajar CSV", false), new Todo(2, "Beli kopi, gula", true));
        String csv = mapper.writer(schema).writeValueAsString(daftar);
        System.out.print(csv);
    }
}

@JsonPropertyOrder({"id", "judul", "selesai"})
class Todo {
    public int id;
    public String judul;
    public boolean selesai;

    public Todo() {
    }

    Todo(int id, String judul, boolean selesai) {
        this.id = id;
        this.judul = judul;
        this.selesai = selesai;
    }
}

import java.io.*;
import java.util.*;

import com.fasterxml.jackson.annotation.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.dataformat.csv.*;

public class Main {
    public static void main(String[] args) throws IOException {
        CsvMapper mapper = new CsvMapper();
        CsvSchema schema = mapper.schemaFor(Todo.class).withHeader();
        List<Todo> daftar = Arrays.asList(new Todo(1, "Belajar CSV", false), new Todo(2, "Beli kopi, gula", true));
        String csv = mapper.writer(schema).writeValueAsString(daftar);
        System.out.print(csv);

        List<Todo> dibaca;
        try (MappingIterator<Todo> it = mapper.readerFor(Todo.class).with(schema).readValues(csv)) {
            dibaca = it.readAll();
        }
        for (Todo t : dibaca) {
            System.out.println(t.id + " " + t.judul + " " + t.selesai);
        }
    }
}

